 String webThemeScript(){return "(function(){const accent="+JSONObject.quote(hex(green))+", light="+JSONObject.quote(hex(blend(green,Color.WHITE,.85f)))+";for(const e of document.querySelectorAll('body *')){if(e.closest('script,style,iframe,svg'))continue;let st=getComputedStyle(e);for(const k of ['color','background-color','border-top-color','border-right-color','border-bottom-color','border-left-color']){let mark='data-abon-tone-'+k;let tone=e.getAttribute(mark);if(!tone){let m=st.getPropertyValue(k).match(/^rgba?\\(\\s*(\\d+),\\s*(\\d+),\\s*(\\d+)(?:,\\s*([\\d.]+))?\\)$/);if(!m||m[4]==='0')continue;let r=+m[1],g=+m[2],b=+m[3];if(g-r<9||g-b<6)continue;tone=(Math.min(r,g,b)>170?'light':'accent');e.setAttribute(mark,tone);}e.style.setProperty(k,tone==='light'?light:accent,'important');}}})()";}
