 void cleanAndInspect(String url){
  final int g=generation;
  String css=webCss(url);
  String script="(function(){let st=document.getElementById('abonclient-clean');if(!st){st=document.createElement('style');st.id='abonclient-clean';document.head.appendChild(st);}st.textContent="+JSONObject.quote(css)+";"+
   "for(const h of document.querySelectorAll('h1,h2,h3,.card-title,.page_title__text')){if(/^(Поділитися|Комунальна п[’'ʼ]ятірка)$/i.test(h.textContent.trim())){let b=h.closest('section')||h.closest('.card');if(b)b.style.setProperty('display','none','important');}}"+
   "if(location.pathname.startsWith('/account/meter/')){for(const el of document.querySelectorAll('label,th,td,span,div,p,b,strong')){if(el.children.length===0){let t=el.textContent.trim();if(/^(Новий показ|Різниця):?$/i.test(t)){el.classList.add('abon-meter-label');if(/^Різниця/i.test(t)){let target=el.nextElementSibling||el.parentElement.nextElementSibling;if(target)target.classList.add('abon-difference');}}}}for(const el of document.querySelectorAll('[id*=difference],[class*=difference],[id*=diff],[class*=diff]')){if(!/^Різниця:?$/i.test(el.textContent.trim()))el.classList.add('abon-difference');}for(const el of document.querySelectorAll('form input:not([type=hidden]):not([type=submit]):not([type=button]):not([type=checkbox]):not([type=radio])')){if(!el.readOnly&&!el.disabled&&['text','number','tel'].includes(el.type))el.classList.add('abon-new-reading');}for(const el of document.querySelectorAll('input[type=submit],button,a')){if(el.matches('input[type=submit],button[type=submit]')||/^(Надіслати|Відправити)$/i.test((el.value||el.textContent).trim()))el.classList.add('abon-submit');}for(const el of document.querySelectorAll('a[href*=\"/account/reading/history/\"]'))el.classList.add('abon-history-button');}if(location.pathname.startsWith('/account/reading/history/')){for(const el of document.querySelectorAll('a[href*=\"/account/meter/\"]'))el.classList.add('abon-history-button');}"+
   "const q=(s,r=document)=>r.querySelector(s),t=(s,r=document)=>{let e=q(s,r);return e?e.textContent.trim():''},a=(s)=>{let e=q(s);return e?e.href:''};"+
   "const logged=document.body.classList.contains('user-logged-in');"+
   "if(!logged)return JSON.stringify({kind:'login',login:a('a[href*=\"/user/login\"]'),register:a('a[href*=\"/user/register\"]'),password:a('a[href*=\"/user/password\"]'),form:!!q('form input[type=password]')});"+
   "if(q('.ai_account_state'))return JSON.stringify({kind:'account',company:t('.cmb_company_name'),code:t('.account_title_code'),balance:t('.ai_payment_data .ai_account_balance'),meters:Array.from(document.querySelectorAll('.ai_meters tbody tr')).map(r=>Array.from(r.cells).map(c=>c.textContent.trim())),groups:Array.from(document.querySelectorAll('.ai_mutual_settlements li')).map(r=>({name:t('.ai_mutual_settlements_agreement_type_name',r),rows:Array.from(r.querySelectorAll('tbody tr')).map(x=>Array.from(x.cells).map(c=>c.textContent.trim()))})),reading:a('a[href*=\"/account/meter/\"]'),history:a('a[href*=\"/account/reading/history/\"]'),payments:a('a[href*=\"/account/payment/list/\"]')});"+
   "if(location.pathname==='/account/list'){let seen=new Set(),accounts=[];for(const e of document.querySelectorAll('a[href*=\"/account/index/\"]')){if(!seen.has(e.href)){seen.add(e.href);accounts.push({url:e.href,label:e.textContent.trim()});}}return JSON.stringify({kind:'list',accounts:accounts});}return JSON.stringify({kind:'other'});})()";
  web.evaluateJavascript(script,value->{if(g!=generation||!trusted(web.getUrl())||!url.equals(web.getUrl()))return;try{
   web.evaluateJavascript(webThemeScript(),null);Object raw=new JSONTokener(value).nextValue();JSONObject o=new JSONObject((String)raw);String kind=o.optString("kind");
   if(kind.equals("account")){commitLoginCandidate();accountUrl=url;data=o;pendingEmail=null;pendingPassword=null;loginAttempt=false;showSiteForm=false;if(!settings)showDashboard();}
   else if(kind.equals("list")){commitLoginCandidate();pendingEmail=null;pendingPassword=null;loginAttempt=false;showSiteForm=false;if(!settings){JSONArray accounts=o.optJSONArray("accounts");if(autoOpen&&accounts!=null&&accounts.length()==1&&trusted(accounts.getJSONObject(0).optString("url"))){autoOpen=false;page(accounts.getJSONObject(0).optString("url"));}else {autoOpen=false;select(1);title.setText("Мої рахунки");reveal();}}}
   else if(kind.equals("login")){data=null;accountUrl="";if(trusted(o.optString("login")))loginUrl=o.optString("login");if(trusted(o.optString("register")))registerUrl=o.optString("register");if(trusted(o.optString("password")))passwordUrl=o.optString("password");if(settings)return;
    if(pendingPassword!=null&&o.optBoolean("form")){submitLogin();return;}
    if(pendingPassword!=null){pendingEmail=null;pendingPassword=null;loginAttempt=false;discardLoginCandidate();showLogin("Не вдалося відкрити форму входу. Спробуйте ще раз.");return;}
    if(loginAttempt){loginAttempt=false;discardLoginCandidate();showSiteForm=false;showLogin("Не вдалося увійти. Перевірте пошту та пароль.");return;}
    if(showSiteForm)reveal();else showLogin("");
   }else {commitLoginCandidate();if(!settings)reveal();}
  }catch(Exception e){pendingEmail=null;pendingPassword=null;discardLoginCandidate();loginAttempt=false;if(!settings)reveal();}});
 }
