  text(p,"Електронна пошта",14,dark,true);EditText email=new EditText(this);email.setSingleLine(true);email.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);email.setHint("Введіть e-mail");email.setBackgroundTintList(android.content.res.ColorStateList.valueOf(green));email.setText(vault.email());p.addView(email);
  text(p,"Пароль",14,dark,true);EditText pass=new EditText(this);pass.setSingleLine(true);pass.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);pass.setHint("Введіть пароль");pass.setBackgroundTintList(android.content.res.ColorStateList.valueOf(green));pass.setText(vault.password());p.addView(pass);
  CheckBox show=new CheckBox(this);show.setText("Показати пароль");show.setButtonTintList(controlTint());p.addView(show);show.setOnCheckedChangeListener((v,c)->{pass.setTransformationMethod(c?null:android.text.method.PasswordTransformationMethod.getInstance());pass.setSelection(pass.length());});
