 LinearLayout m=card(-1);text(m,"Лічильники",22,dark,true);JSONArray meters=data.optJSONArray("meters");if(meters!=null)for(int i=0;i<meters.length();i++){JSONArray r=meters.optJSONArray(i);if(r!=null){centered(m,r.optString(0),16,dark,false);centered(m,r.optString(1),48,green,true);centered(m,"Останній показник",14,dark,false);}}
 LinearLayout actions=new LinearLayout(this);actions.setOrientation(0);m.addView(actions,new LinearLayout.LayoutParams(-1,-2));String[] keys={"reading","history"},labels={"Подати показники","Історія показників"};for(int i=0;i<2;i++){String u=data.optString(keys[i]);if(trusted(u)){Button btn=greenButton(labels[i],()->page(u));btn.setTextSize(14);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(64),1);lp.setMargins(dp(3),dp(8),dp(3),0);actions.addView(btn,lp);}}
