 void showSettings(){settings=true;dashboard=false;select(3);begin("Налаштування");LinearLayout p=card(-1);text(p,"Версія "+versionName(),20,dark,true);button(p,"Перевірити оновлення",()->checkUpdate(true));Switch s=new Switch(this);s.setText("Перевіряти при запуску");s.setTextSize(18);s.setTextColor(dark);s.setThumbTintList(controlTint());s.setTrackTintList(controlTint());s.setPadding(0,dp(16),0,dp(16));s.setChecked(getPreferences(0).getBoolean("autoUpdate",false));p.addView(s);s.setOnCheckedChangeListener((v,c)->getPreferences(0).edit().putBoolean("autoUpdate",c).apply());themePicker(p);button(p,"Очистити збережені дані входу",()->new AlertDialog.Builder(this).setMessage("Видалити збережену пошту та пароль з цього телефону?").setNegativeButton("Ні",null).setPositiveButton("Так",(d,w)->{discardLoginCandidate();vault.clear();toast("Збережені дані видалено");}).show());button(p,"Вийти з кабінету",()->new AlertDialog.Builder(this).setMessage("Очистити локальну сесію?").setNegativeButton("Ні",null).setPositiveButton("Так",(d,w)->{data=null;accountUrl="";autoOpen=true;showSiteForm=false;loginAttempt=false;discardLoginCandidate();pendingEmail=null;pendingPassword=null;CookieManager.getInstance().removeAllCookies(x->{CookieManager.getInstance().flush();page(LIST);});}).show());}
 String versionName(){try{return getPackageManager().getPackageInfo(getPackageName(),0).versionName;}catch(Exception e){return "1.5";}}
 int versionCode(){try{return getPackageManager().getPackageInfo(getPackageName(),0).versionCode;}catch(Exception e){return 0;}}
 void checkUpdate(boolean manual){if(manual)toast("Перевіряємо оновлення…");new Thread(()->{try{URL u=new URL("https://api.github.com/repos/1796caesar-cmd/AbonClient/releases/latest");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(10000);c.setReadTimeout(10000);c.setRequestProperty("Accept","application/vnd.github+json");c.setRequestProperty("User-Agent","AbonClient");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}finally{c.disconnect();}JSONObject r=new JSONObject(out.toString("UTF-8"));String tag=r.optString("tag_name");int remote=Integer.parseInt(tag.substring(tag.lastIndexOf('-')+1));String download="";JSONArray assets=r.getJSONArray("assets");for(int i=0;i<assets.length();i++){JSONObject a=assets.getJSONObject(i);if(a.optString("name").equals("AbonClient.apk"))download=a.optString("browser_download_url");}final String link=download;runOnUiThread(()->{if(isFinishing()||isDestroyed())return;if(remote>versionCode()&&link.startsWith(REPO+"/releases/download/"))new AlertDialog.Builder(this).setTitle("Доступне оновлення").setMessage(r.optString("name",tag)).setNegativeButton("Пізніше",null).setPositiveButton("Завантажити та встановити",(d,w)->updater.download(link,remote)).show();else if(manual)toast("Новішої версії не знайдено");});}catch(Exception e){if(manual)runOnUiThread(()->toast("Не вдалося перевірити оновлення"));}}).start();}
 void settlementTable(LinearLayout parent,JSONArray rows){
  LinearLayout table=new LinearLayout(this);table.setOrientation(1);parent.addView(table,new LinearLayout.LayoutParams(-1,-2));
  addTableRow(table,new String[]{"Дата","Нараховано","Сплачено","Залишок"},true,0);
  for(int i=0;i<Math.min(3,rows.length());i++){JSONArray r=rows.optJSONArray(i);if(r==null||r.length()<4)continue;String date=r.optString(0);if(date.matches("[0-9]{4}-[0-9]{2}"))date=date.substring(5)+"."+date.substring(0,4);addTableRow(table,new String[]{date,r.optString(1).replace('.',','),r.optString(2).replace('.',','),r.optString(3).replace('.',',')},false,i);}
  text(parent,"Усі суми в гривнях",12,dark,false);
 }
 void addTableRow(LinearLayout table,String[] values,boolean header,int index){
  LinearLayout row=new LinearLayout(this);row.setOrientation(0);row.setGravity(Gravity.CENTER_VERTICAL);row.setBackgroundColor(header?blend(green,Color.WHITE,.84f):(index%2==0?bg:Color.WHITE));
  for(int i=0;i<4;i++){TextView cell=new TextView(this);cell.setText(values[i]);cell.setTextSize(header?10:12);cell.setTextColor(header?green:dark);cell.setGravity(Gravity.CENTER);cell.setPadding(dp(1),dp(10),dp(1),dp(10));if(header)cell.setTypeface(null,Typeface.BOLD);row.addView(cell,new LinearLayout.LayoutParams(0,-2,i==1?1.2f:1f));}
  table.addView(row,new LinearLayout.LayoutParams(-1,-2));
 }
 @Override protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(updater!=null)updater.onActivityResult(request,result);}
 @Override protected void onDestroy(){if(updater!=null)updater.destroy();super.onDestroy();}
 @Override public void onBackPressed(){if(settings||dashboard){if(settings)home();else accounts();}else if(data!=null)showDashboard();else if(showSiteForm){showSiteForm=false;page(LIST);}else if(web.canGoBack())web.goBack();else super.onBackPressed();}
 @Override protected void onPause(){super.onPause();CookieManager.getInstance().flush();}
